package co.edu.cinematch.core.model;
public class Sala implements Identifiable { private String id; private String cineId; private String nombre; private int capacidad; private String tipo; public Sala(){} public Sala(String cineId,String nombre,int capacidad,String tipo){this.cineId=cineId;this.nombre=nombre;this.capacidad=capacidad;this.tipo=tipo;} public String getId(){return id;}public void setId(String v){id=v;}public String getCineId(){return cineId;}public void setCineId(String v){cineId=v;}public String getNombre(){return nombre;}public void setNombre(String v){nombre=v;}public int getCapacidad(){return capacidad;}public void setCapacidad(int v){capacidad=v;}public String getTipo(){return tipo;}public void setTipo(String v){tipo=v;} }
